import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    N = next(it)
    M = next(it)
    parent = list(range(N+1))
    size = [1]*(N+1)
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a,b):
        a = find(a); b = find(b)
        if a == b: return
        if size[a] < size[b]:
            a,b = b,a
        parent[b] = a
        size[a] += size[b]

    for _ in range(M):
        u = next(it); v = next(it)
        if u != v:
            union(u,v)
        else:
            # self-loop: doesn't change components
            pass

    K = next(it)
    forbidden = set()
    for _ in range(K):
        x = next(it); y = next(it)
        rx = find(x); ry = find(y)
        if rx == ry:
            # problem statement guarantees they are disconnected initially
            continue
        if rx > ry:
            rx,ry = ry,rx
        forbidden.add((rx,ry))

    Q = next(it)
    out_lines = []
    for _ in range(Q):
        p = next(it); q = next(it)
        rp = find(p); rq = find(q)
        if rp == rq:
            out_lines.append("Yes")
        else:
            a,b = (rp,rq) if rp < rq else (rq,rp)
            if (a,b) in forbidden:
                out_lines.append("No")
            else:
                out_lines.append("Yes")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
