def is_acronym(words: list[str], s: str) -> bool:
    """
    Return True if `s` is the acronym formed by concatenating the first
    character of each string in `words` in order; otherwise False.
    """
    if len(s) != len(words):
        return False
    return s == ''.join(word[0] for word in words)

