def permutation_difference(s: str, t: str) -> int:
    """
    Compute the permutation difference between s and t:
    sum of absolute differences of indices for each character.
    Assumes characters in s are unique and t is a permutation of s.
    """
    pos_s = {ch: i for i, ch in enumerate(s)}
    return sum(abs(pos_s[ch] - i) for i, ch in enumerate(t))

